const f = $input.first().json;
const num = parseInt(f['Number of Questions'], 10);
const typeRaw = f['Question Type'];
const diff = f['Difficulty'];
// AR ↔ A&R aliasing: form value is 'AR'; final JSON uses 'A&R' per spec UI; folder uses 'AR'.
const typeKey = typeRaw === 'A&R' ? 'AR' : typeRaw;
const typeOut = typeKey === 'AR' ? 'A&R' : typeKey;

const batchId = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
const chapterCode = (f['Chapter Name'] || 'CHP').toUpperCase().replace(/[^A-Z0-9]+/g, '_').slice(0, 12);
const diffCode = ({ EASY: 'E', MEDIUM: 'M', HARD: 'H' })[diff] || 'M';

// Resolve the selected prompt + the three system prompts from the hidden form fields.
const promptKey = `PROMPT_${typeKey}_${diff}`;
const selectedPrompt = f[promptKey];
if (!selectedPrompt) throw new Error(`Missing hidden prompt field: ${promptKey}`);

return [{
  json: {
    board: f['Board'],
    class_name: f['Class'],
    chapter: f['Chapter Name'],
    source_type: f['Source Type'],
    question_type: typeOut,
    question_type_folder: typeKey,
    difficulty: diff,
    number_of_questions: Number.isFinite(num) && num > 0 ? num : 10,
    include_visual_questions: (f['Include Visual Questions'] || 'NO').toUpperCase() === 'YES',
    language: f['Language'] || 'English',
    generate_explanation: (f['Generate Explanation'] || 'YES').toUpperCase() === 'YES',
    prompt_key: `${typeKey}_${diff}`,
    chapter_code: chapterCode,
    difficulty_code: diffCode,
    batch_id: batchId,
    started_at: new Date().toISOString(),
    selected_prompt: selectedPrompt,
    system_generator: f['SYSTEM_GENERATOR'],
    system_structurer: f['SYSTEM_STRUCTURER'],
    system_validator: f['SYSTEM_VALIDATOR'],
    attempt: 0
  },
  binary: $input.first().binary
}];

// Cleans headers, footers, page numbers, repeated lines, OCR artefacts, URLs, and duplicate paragraphs.
const raw = ($json.text || '').toString();
let t = raw.replace(/Page\s+\d+\s+of\s+\d+/gi, '');
t = t.split('\n').filter(l => !/^\s*\d{1,3}\s*$/.test(l)).join('\n');
const freq = new Map();
t.split('\n').forEach(l => { const k = l.trim(); if (k.length > 0 && k.length < 80) freq.set(k, (freq.get(k) || 0) + 1); });
const headers = new Set([...freq].filter(([, c]) => c > 5).map(([k]) => k));
t = t.split('\n').filter(l => !headers.has(l.trim())).join('\n');
t = t.replace(/-\n(\w)/g, '$1');
t = t.replace(/[ \t]{2,}/g, ' ');
t = t.replace(/\n{3,}/g, '\n\n');
t = t.replace(/[\u0000-\u001F\u007F]/g, ' ');
t = t.split('\n').filter(l => !/^(https?:|www\.|email:)/i.test(l.trim())).join('\n');
const paras = t.split(/\n\n+/);
const dedup = [];
for (const p of paras) { if (dedup[dedup.length - 1] !== p) dedup.push(p); }
return [{ json: { ...$('Normalize Input').first().json, cleaned_text: dedup.join('\n\n').trim() } }];

